53	        List<Integer> path = result.getPath(from, to);
54	        if (path.isEmpty()) {
55	            System.out.printf("%d -> %d: unreachable%n", from, to);
56	        } else {
57	            String pathStr = path.stream().map(String::valueOf).collect(Collectors.joining(" -> "));
58	            System.out.printf("%d -> %d (dist=%d): %s%n",
59	                from, to, result.getDistance(from, to), pathStr);
60	        }
61	    }
62	}
